public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("Day step must be a positive integer");
    }
    long days = timeBucket / 1000000L;
    long remainder = timeBucket % 1000000L;
    long step = days / dayStep;
    long newDays = step * dayStep;
    long newRemainder = remainder;
    if (newRemainder >= 1000000L) {
        newRemainder = 0;
    }
    return newDays * 1000000L + newRemainder;
}
